var page = new XDocument(new XElement("invoice",          // stage 1: logical page
    new XAttribute("total", "42.00"),
    new XElement("customer", "ACME")));

var xslt = new XslCompiledTransform();
xslt.Load("invoice-html.xsl");                            // compiled once, reused
using var w = new StringWriter();
xslt.Transform(page.CreateReader(), null, w);              // stage 2: render
